<?php
declare(strict_types=1);
namespace VeciAhorra\Modules\Sectorization;
use VeciAhorra\Core\Session;
final class CurrentSector { private const META='_veciahorra_service_zone_id';private const SESSION='veciahorra_service_zone_id';public function __construct(private ServiceZoneRepository $zones=new ServiceZoneRepository()){}public function id():int{$id=is_user_logged_in()?self::normalizedId(get_user_meta(get_current_user_id(),self::META,true)):self::normalizedId(Session::get(self::SESSION,0));return $id>0&&$this->zones->findActive($id)!==null?$id:0;}public function set(int $id):array{$zone=$this->zones->findActive($id)??throw new \InvalidArgumentException('El sector no existe o está inactivo.');$persisted=is_user_logged_in()?$this->persistUser(get_current_user_id(),$id):Session::putVerifiedAndClose(self::SESSION,$id);if(!$persisted)throw new \RuntimeException('sector_persistence_failed');return $zone;}public function current():?array{$id=$this->id();return $id?$this->zones->findActive($id):null;}private function persistUser(int $userId,int $id):bool{update_user_meta($userId,self::META,$id);return self::normalizedId(get_user_meta($userId,self::META,true))===$id;}private static function normalizedId(mixed $value):int{if(is_int($value))return $value>0?$value:0;if(!is_string($value)||preg_match('/^[1-9]\d*$/D',$value)!==1)return 0;$id=(int)$value;return $id>0?$id:0;}}
